(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.28)*12;
  const w2x = Math.sin((x+w1x)*0.032+t*0.45)*8 + Math.cos((y+w1y)*0.028-t*0.38)*6;
  const w2y = Math.cos((y+w1y)*0.03-t*0.4)*8 + Math.sin((x+w1x)*0.025+t*0.48)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 75+Math.cos(t*0.35)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.45)*100, 165+Math.sin(t*0.6)*55, 0.09, 1.8, 1.0],
    [240+Math.sin(t*0.28+2)*150, 115+Math.cos(t*0.42+1)*95, 0.055, 2.4, 0.7],
    [115+Math.cos(t*0.7+1)*85, 185+Math.sin(t*0.5+3)*65, 0.11, 1.6, 1.1],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 0.9],
    [240+Math.cos(t*0.32+5)*130, 205+Math.sin(t*0.48)*85, 0.085, 2.0, 0.85],
    [80+Math.sin(t*0.55+3)*70, 50+Math.cos(t*0.65+1)*60, 0.1, 1.4, 1.05],
    [400+Math.cos(t*0.42+2)*80, 200+Math.sin(t*0.52+4)*70, 0.07, 2.2, 0.75]
  ];
  let aS=0, iS=0, glow=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp), w2=Math.sin(d*f*1.618-t*sp*0.7+2.0);
    aS+=w1*w+w2*(1-w); iS+=Math.sin(d*f*0.7+t*sp*0.55+1.5)*w;
    glow+=Math.exp(-d*0.008)*Math.abs(w1)*0.3;
  }
  const act=aS/8, inh=iS/8, glowN=glow/8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.2+Math.sin((sx-sy)*0.09-t*1.8)*0.2
    +Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.055-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
