  const ny=Math.cos(sx*0.1-t*0.7)*Math.sin(sy*0.13+t*0.9);
  const voronoi=Math.min(
    Math.sqrt((sx%40-20+nx*5)**2+(sy%40-20+ny*5)**2),
    Math.sqrt(((sx+20)%40-20+ny*5)**2+((sy+20)%40-20+nx*5)**2)
  );
  const cellEdge=Math.max(0, 1-voronoi*0.12);
  const reaction=Math.tanh((act-inh*0.65+bg*0.35+spiral+cellEdge*0.4)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+nx*ny*0.3)*1.5)*0.25;
  const breathe=0.92+Math.sin(t*0.4)*0.08;
  const blend=(reaction*0.6+cell*0.2+glowN*0.15+spiral*0.05)*breathe;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,95,125],[30,155,145],[80,185,130],
    [180,195,80],[220,165,55],[215,110,65],[185,60,70],[130,35,75],
    [70,22,60],[30,12,48],[5,12,52]
